/**
 * src/lib/base-foods.js — search over the bundled base-ingredient catalogue.
 *
 * Backs the "Básicos" source on the Foods screen: onion, potato, almonds,
 * chicken breast — the unbranded, unpackaged things Open Food Facts is bad at
 * and USDA only answers in English behind an API key.
 *
 * The data ships with the app (src/lib/base-foods.json, generated by
 * scripts/build-base-foods.mjs), so this source needs no network, no key, and
 * works offline and on Capacitor exactly as it does on the web.
 *
 * The JSON is pulled in with a dynamic import() so it lands in its own chunk
 * and costs nothing until the user actually searches.
 */

// Display names for the catalogue's own categories. These are ours, not the
// user's curated food categories — a catalogue entry deliberately ships with
// an empty `categories` so it never writes into that list (see toResult).
const CATEGORY_LABELS = {
  aceites:        { es: 'Aceites y grasas',  en: 'Oils & fats' },
  bebidas:        { es: 'Bebidas',           en: 'Drinks' },
  carnes:         { es: 'Carnes',            en: 'Meat' },
  cereales:       { es: 'Cereales y panes',  en: 'Grains & bread' },
  condimentos:    { es: 'Condimentos',       en: 'Seasonings' },
  dulces:         { es: 'Dulces',            en: 'Sweets' },
  frutas:         { es: 'Frutas',            en: 'Fruit' },
  'frutos-secos': { es: 'Frutos secos',      en: 'Nuts & seeds' },
  lacteos:        { es: 'Lácteos y huevos',  en: 'Dairy & eggs' },
  legumbres:      { es: 'Legumbres',         en: 'Legumes' },
  pescados:       { es: 'Pescados y mariscos', en: 'Fish & seafood' },
  verduras:       { es: 'Verduras',          en: 'Vegetables' },
};

/** Human-readable name for a catalogue category slug. */
export function categoryLabel(slug, locale = 'es') {
  const e = CATEGORY_LABELS[slug];
  if (!e) return slug;
  return String(locale || '').startsWith('es') ? e.es : e.en;
}

let _catalogue = null;    // resolved JSON document
let _index = null;        // [{ food, haystack: [normalised strings] }]
let _loadPromise = null;  // single-flight guard

/**
 * Fold a string down to something searchable: lowercase, no accents, no
 * punctuation. This is what lets "platano" find "Plátano" and "jalapeno"
 * find "Jalapeño" — a Spanish catalogue searched from a keyboard where
 * people rarely bother with accents.
 */
export function normalize(s) {
  return String(s || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')   // strip combining diacritics
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

async function load() {
  if (_catalogue) return _catalogue;
  if (_loadPromise) return _loadPromise;
  // The `with { type: 'json' }` attribute is required by Node (so this module
  // is unit-testable outside a bundler) and understood by Vite/Rollup.
  _loadPromise = import('./base-foods.json', { with: { type: 'json' } }).then(mod => {
    _catalogue = mod.default || mod;
    _index = _catalogue.foods.map(food => ({
      food,
      // Names first, aliases after — the scorer rewards an early hit, so a
      // food matched on its own name outranks one matched on a synonym.
      haystack: [
        normalize(food.name.es),
        normalize(food.name.en),
        ...(food.alias?.es || []).map(normalize),
      ].filter(Boolean),
    }));
    return _catalogue;
  });
  return _loadPromise;
}

/** Catalogue metadata (source, release, licence) for the About/Settings screen. */
export async function catalogueInfo() {
  const c = await load();
  return { version: c.version, generated: c.generated, source: c.source, count: c.foods.length };
}

/** Category slugs present in the catalogue, e.g. ['aceites', 'bebidas', …]. */
export async function categories() {
  return (await load()).categories.slice();
}

// Lower score = better match. The gap between tiers is wide enough that an
// exact hit always beats a prefix hit on a shorter word, etc.
function scoreEntry(haystack, q) {
  let best = Infinity;
  for (let i = 0; i < haystack.length; i++) {
    const h = haystack[i];
    // Alias hits are demoted by one tier so "Palta" ranks above a food that
    // merely lists "palta" as a synonym.
    const penalty = i < 2 ? 0 : 1;
    let s;
    if (h === q) s = 0;
    else if (h.startsWith(q)) s = 10;
    else if (new RegExp(`\\b${q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`).test(h)) s = 20;
    else if (h.includes(q)) s = 30;
    else continue;
    best = Math.min(best, s + penalty);
  }
  return best;
}

/**
 * Shape one catalogue row like the objects the other search sources emit
 * (see USDA._mapProduct / API._mapOFFProduct in api.js), so the Foods screen,
 * the food editor and the diary can consume all sources through one path.
 *
 * Deliberately emits NO `id`, exactly like _mapOFFProduct and USDA._mapProduct.
 * A search hit is not a row in the user's library yet, and FoodEditor.save()
 * branches on plain truthiness (`food.id ? updateFood : createFood`), so any
 * id at all -- even a string -- sends it down the update path and the server
 * answers 404 "Not found". Callers de-duplicate on `barcode`, which is unique
 * per catalogue entry.
 */
function toResult(food, locale) {
  const es = String(locale || '').startsWith('es');
  return {
    name:      es ? food.name.es : food.name.en,
    brand:     '',
    // Mirrors the fdcId_ convention the USDA source uses, so a saved food
    // keeps a traceable pointer back to the SR Legacy row it came from.
    //
    // An approximated entry borrows another food's row but is NOT that food,
    // so it must not claim its barcode: two results sharing one would collide
    // in the keyed {#each} that renders them, and Svelte throws on duplicate
    // keys — the failure that took the whole search view down once already.
    // It would also make the library swap replace both with one saved copy.
    barcode:   food.approx ? 'ntBase_' + food.id : 'fdcId_' + food.fdc,
    unit:      'g',
    portion:   100,
    quantity:  1,
    imgUrl:    '',
    dateTime:  new Date().toISOString(),
    // Left empty on purpose, matching USDA._mapProduct. `category` on a saved
    // food maps to the user's own curated `foodCategories` list; injecting our
    // catalogue's taxonomy ('verduras', 'aceites') into it would invent
    // categories they never created. The slug stays on _baseCategory instead.
    categories: [],
    nutrition: food.nutrition,
    // Household portions ("1 unidad mediana = 110 g"). createFood() spreads
    // this straight through to the foods table's alt_units column.
    alt_units: food.units,
    // Substitution hint, precomputed by scripts/build-base-foods.mjs and
    // committed with the catalogue so the criteria stay auditable.
    _light:    food.light,
    _source:   'base',
    _baseId:   food.id,
    _baseCategory: food.cat,
    _baseCategoryLabel: categoryLabel(food.cat, locale),
  };
}

/**
 * Search the catalogue. Mirrors the (query, page, pageSize) contract of
 * API.searchByNameWithMeta / USDA.searchByNameWithMeta so Foods.svelte can
 * treat every source the same way.
 *
 * Returns { items, totalHits, hasMore, page }.
 */
export async function searchByNameWithMeta(query, page = 1, pageSize = 50, opts = {}) {
  await load();
  const q = normalize(query);
  if (!q) return { items: [], totalHits: 0, hasMore: false, page: 1 };

  const cat = opts.category || null;
  const scored = [];
  for (const entry of _index) {
    if (cat && entry.food.cat !== cat) continue;
    const score = scoreEntry(entry.haystack, q);
    if (score === Infinity) continue;
    scored.push({ entry, score });
  }

  const locale = opts.locale || 'es';
  scored.sort((a, b) =>
    a.score - b.score ||
    a.entry.food.name.es.localeCompare(b.entry.food.name.es, 'es'));

  const start = (page - 1) * pageSize;
  const items = scored.slice(start, start + pageSize).map(s => toResult(s.entry.food, locale));
  return {
    items,
    totalHits: scored.length,
    hasMore: start + pageSize < scored.length,
    page,
  };
}

/** Convenience wrapper matching the plain searchByName shape of the other sources. */
export async function searchByName(query, page = 1, opts = {}) {
  const r = await searchByNameWithMeta(query, page, 50, opts);
  return r.items;
}

/**
 * Every food in a category, alphabetical. Powers browsing the catalogue with
 * an empty search box — the "I don't know what it's called, show me the
 * vegetables" path, which is the whole point of having a curated list.
 */
export async function browse(category, locale = 'es') {
  await load();
  return _catalogue.foods
    .filter(f => !category || f.cat === category)
    .map(f => toResult(f, locale));
}

export const BaseFoods = {
  normalize, catalogueInfo, categories, categoryLabel, searchByName, searchByNameWithMeta, browse,
};
